#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <fstream>
#include <ctime>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <openssl/evp.h>
#include <openssl/pem.h>

namespace crypto_audit {

static const std::vector<std::string> ALLOWED_OCSP_HOSTS = {
    "ocsp.digicert.com",
    "ocsp.letsencrypt.org",
    "ocsp.pki.goog",
    "ocsp.comodoca.com",
    "ocsp.entrust.net"
};

static bool is_allowed_ocsp_host(const std::string& host) {
    for (const auto& allowed : ALLOWED_OCSP_HOSTS) {
        if (host == allowed) return true;
    }
    return false;
}

static bool is_internal_address(const std::string& host) {
    struct hostent* he = gethostbyname(host.c_str());
    if (!he) return true; // deny on resolution failure

    uint32_t addr;
    memcpy(&addr, he->h_addr, 4);
    addr = ntohl(addr);

    // Block RFC1918, loopback, link-local, metadata
    if ((addr & 0xFF000000) == 0x0A000000) return true;  // 10.0.0.0/8
    if ((addr & 0xFFF00000) == 0xAC100000) return true;  // 172.16.0.0/12
    if ((addr & 0xFFFF0000) == 0xC0A80000) return true;  // 192.168.0.0/16
    if ((addr & 0xFF000000) == 0x7F000000) return true;  // 127.0.0.0/8
    if ((addr & 0xFFFF0000) == 0xA9FE0000) return true;  // 169.254.0.0/16
    if (addr == 0x00000000) return true;                  // 0.0.0.0

    return false;
}

class AuditLogger {
public:
    AuditLogger(const std::string& log_path) : log_path_(log_path) {}

    void log_event(const std::string& event_type, const std::string& details) {
        std::time_t now = std::time(nullptr);
        std::string entry = "[" + std::string(std::ctime(&now)) + "] " + event_type + ": " + details;
        entries_.push_back(entry);
    }

    bool flush_to_file() {
        if (entries_.empty()) return true;
        std::ofstream ofs(log_path_, std::ios::app);
        if (!ofs.is_open()) return false;
        for (const auto& e : entries_) ofs << e << "\n";
        entries_.clear();
        return true;
    }

private:
    std::string log_path_;
    std::vector<std::string> entries_;
};

class CertificateValidator {
public:
    CertificateValidator(AuditLogger& logger) : logger_(logger) {}

    bool validate_certificate_chain(const std::string& pem_cert, const std::string& ocsp_responder_url) {
        logger_.log_event("CERT_VALIDATION", "Starting chain validation");

        BIO* bio = BIO_new_mem_buf(pem_cert.c_str(), pem_cert.size());
        if (!bio) {
            logger_.log_event("CERT_ERROR", "Failed to create BIO");
            return false;
        }

        X509* cert = PEM_read_bio_X509(bio, nullptr, nullptr, nullptr);
        BIO_free(bio);
        if (!cert) {
            logger_.log_event("CERT_ERROR", "Failed to parse certificate");
            return false;
        }

        std::string subject = get_subject_name(cert);
        logger_.log_event("CERT_INFO", "Subject: " + subject);

        bool ocsp_valid = check_ocsp_status(cert, ocsp_responder_url);

        X509_free(cert);
        logger_.log_event("CERT_VALIDATION", "Result: " + std::string(ocsp_valid ? "VALID" : "INVALID"));
        return ocsp_valid;
    }

private:
    AuditLogger& logger_;

    std::string get_subject_name(X509* cert) {
        char buf[256];
        char* res = X509_NAME_oneline(X509_get_subject_name(cert), buf, sizeof(buf));
        if (!res) return std::string();
        return std::string(buf);
    }

    bool check_ocsp_status(X509* cert, const std::string& responder_url) {
        logger_.log_event("OCSP_CHECK", "Contacting responder: " + responder_url);

        std::string host;
        int port = 80;
        std::string path;
        if (!extract_url_components(responder_url, host, port, path)) {
            logger_.log_event("OCSP_DENIED", "Malformed responder URL");
            return false;
        }

        if (!is_allowed_ocsp_host(host)) {
            logger_.log_event("OCSP_DENIED", "Host not in allowlist: " + host);
            return false;
        }

        if (is_internal_address(host)) {
            logger_.log_event("OCSP_DENIED", "Resolved to internal address: " + host);
            return false;
        }

        if (port != 80 && port != 443) {
            logger_.log_event("OCSP_DENIED", "Non-standard port: " + std::to_string(port));
            return false;
        }

        int sock = socket(AF_INET, SOCK_STREAM, 0);
        if (sock < 0) return false;

        struct timeval timeout;
        timeout.tv_sec = 5;
        timeout.tv_usec = 0;
        setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));
        setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout));

        struct hostent* server = gethostbyname(host.c_str());
        if (!server) { close(sock); return false; }

        struct sockaddr_in serv_addr;
        memset(&serv_addr, 0, sizeof(serv_addr));
        serv_addr.sin_family = AF_INET;
        memcpy(&serv_addr.sin_addr.s_addr, server->h_addr, server->h_length);
        serv_addr.sin_port = htons(port);

        if (connect(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
            close(sock);
            return false;
        }

        std::string ocsp_request = build_ocsp_request(cert);
        std::string http_req = "POST " + path + " HTTP/1.1\r\nHost: " + host +
            "\r\nContent-Type: application/ocsp-request\r\nContent-Length: " + 
            std::to_string(ocsp_request.size()) + "\r\n\r\n" + ocsp_request;

        send(sock, http_req.c_str(), http_req.size(), 0);

        char response[4096];
        int bytes = recv(sock, response, sizeof(response) - 1, 0);
        close(sock);

        if (bytes <= 0) return false;
        response[bytes] = '\0';

        return parse_ocsp_response(std::string(response, bytes));
    }

    bool extract_url_components(const std::string& url, std::string& host, int& port, std::string& path) {
        std::string work = url;
        size_t proto_end = work.find("://");
        if (proto_end != std::string::npos) work = work.substr(proto_end + 3);
        size_t path_start = work.find('/');
        if (path_start != std::string::npos) {
            path = work.substr(path_start);
            work = work.substr(0, path_start);
        } else {
            path = "/";
        }
        size_t port_sep = work.find(':');
        if (port_sep != std::string::npos) {
            std::string port_str = work.substr(port_sep + 1);
            if (port_str.empty()) return false;
            for (char c : port_str) {
                if (c < '0' || c > '9') return false;
            }
            try {
                long parsed = std::stol(port_str);
                if (parsed < 1 || parsed > 65535) return false;
                port = static_cast<int>(parsed);
            } catch (const std::exception&) {
                return false;
            }
            host = work.substr(0, port_sep);
        } else {
            host = work;
        }
        if (host.empty()) return false;
        return true;
    }

    std::string build_ocsp_request(X509* cert) {
        unsigned char md[EVP_MAX_MD_SIZE];
        unsigned int md_len;
        X509_digest(cert, EVP_sha256(), md, &md_len);
        return std::string(reinterpret_cast<char*>(md), md_len);
    }

    bool parse_ocsp_response(const std::string& response) {
        return response.find("good") != std::string::npos;
    }
};

} // namespace crypto_audit

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <cert_file> <ocsp_url>" << std::endl;
        return 1;
    }

    std::ifstream cert_file(argv[1]);
    std::string pem_cert((std::istreambuf_iterator<char>(cert_file)),
                          std::istreambuf_iterator<char>());

    std::string ocsp_url = argv[2];

    crypto_audit::AuditLogger logger("/var/log/crypto_audit/validator.log");
    crypto_audit::CertificateValidator validator(logger);

    bool valid = validator.validate_certificate_chain(pem_cert, ocsp_url);

    logger.flush_to_file();

    std::cout << "Certificate validation: " << (valid ? "PASSED" : "FAILED") << std::endl;
    return valid ? 0 : 1;
}
